; get the size of the list	pha	pei <SizeCtlHandle+2	pei <SizeCtlHandle	_NewList2	; and create the new list	rts	;-------------------------------------------------------------------------------;; Get new font size;GetNewSize		pha	pha	pha	pha	PushZLong <LineHndl	;handle to LineEdit	record	_GetCtlTitle	_LEGetTextHand	; get the text handle	pla	sta <TempHandle	;record	pla	sta <TempHandle+2;convert 'Other Size' string to an integer;if length of string is 0, the Dec2Int routine will return a result of 0	pha	;space for result	ldy #2	lda [<TempHandle],y	;ptr to size string	pha	lda [<TempHandle]	pha;; Now get the text length	pha	pha	pha	PushZLong <LineHndl	;handle to LineEdit	record	_GetCtlTitle	_LEGetTextLen	PushWord #0	;unsigned conversion	_Dec2Int	;convert size string into an integer	pla	;get new size	sta <CurSize	;and save it	rts;------------------------------------------------------------------------------SetSizeText; push pointer to string:	lda <FMParamPtr	clc	adc #(TheStr-FMParams)	tax	;temp storage	lda <FMParamPtr+2	adc #0	pha	phx	ldy #(StrLen-FMParams)	lda [<FMParamPtr],y	;length of string	and #$00FF	pha	;length of string	; Now we have to get the line edit control from the lineedit control	pha	pha	PushZLong <LineHndl	;handle to LineEdit	record	_GetCtlTitle		_LESetText	;set the 'Other Size' text	rts;------------------------------------------------------------------------------SelectSizeText	PushWord #0	;selstart	PushWord #3	;selend	pha	pha	PushZLong <LineHndl	;handle to LineEdit	record	_GetCtlTitle		_LESetSelect	;select the 'Other Size' text	rts;-------------------------------------------------------------------------------;; Select the 'Other Size' text, put up an alert and then return;DoAlert	jsr SelectSizeText	;select the 'Other Size' text*** 17-Feb-91 DAL -- now uses ErrorWindow for font size alert	pea $4009	;Bad Input Value (deferred until the dialog appears)	_SysBee