Ptr],y	;and store in MD list entry	jsr IncMDPtr	;point to next MD list entry	dec <Count	;done with all families?	beq Done	;yesNextFam	jsr IncFamPtr	;check next family	bra FamLoopDone; Sort the MD list entries so that they point; to the famnames in alphabetical order***	PushLong #0	pushlong #1	;case-insensitive! (24-Feb-91 DAL)*(push pointer to MDListRect)	ldx <FMParamPtr+2	;high word	lda <FMParamPtr	clc	adc #(MDListRect-FMParams)	bcc NoCarry	inxNoCarry	phx	pha;	_SortList	jsr UnLockFamList	jsr UnLockMDList;	clc	rtsxCountFams	tdc	jsl CountFamilies	rtl	ENDP****************************************************************** DrawGuts*******************************************************************  Changed for ROMming purposes - BHM	x6245  1/11/88	ENTRY DrawGutsDrawGuts	PROC;This routine is called by the Window Manager in order to draw the;contents of the ChooseFont window.*** 17-Feb-91 DAL.  I really don't see what all this crap is for,*** and it seems to work fine if I just do a DrawControls on the*** current port (this is called after BeginUpdate anyway, so we are*** guaranteed that the port is set to our window).	pha	pha	_GetPort	_DrawControls	rtl	ENDP****************************************************************** DrawSize*****************************************************************;** Changed for ROMming purposes - BHM  x6245  1/11/87;	ENTRY DrawSizeDrawSize	PROC;This routine is called by the List Manager whenever it needs to draw;a member of the 'Size' list in the ChooseFont window. Upon	entry to this;routine, the stack	contains the following -;;  Space for result	    4 bytes;  Pointer to member's enclosing rect   4 bytes;  Pointer to member's list entry       4 bytes;  Handle to the list control   4 bytes;  RTL      3 bytes	jsl Doit	;force another return address on stack	rtl	;return to the List	ManagerDoit	phd	;save direct register;get FM's 0-page	pha	; space for result	pha	PushWord #0	; SystemTool flag	PushWord #FMTSNum	; our tool number	_GetWAP	pld	;low word - FM's 0-pagese it	pla	;high word - we don't use it;;dereference but do	not lock FMParams:	lda [<FMParamHandle]	sta <FMParamPtr	ldy #2	lda [<FMParamHandle],y	sta <FMParamPtr+2;	lda 13,s	;get ptr to member's list entry	sta <temp1Ptr	lda 15,s	sta <temp1Ptr+2	lda [<temp1Ptr];	jsr MakeString	;convert size into a string;return ptr to string:	lda <FMParamPtr	clc	adc #(StrLen-FMParams)	sta 21,s	lda <FMParamPtr+2	adc #0	sta 23,s	ldy #12	;param size	jml endcall	;use standard end call to strip params	ENDP****************************************************************** SortSizes*****************************************************************	ENTRY SortSizesSortSizes	PROC;This routine is called by the List Manager routine SortList in order;to sort the 'Size'	list in numerical order. Upon entry to this routine,;the stack contains	the following -;;  Pointer to member B's list entry     4 bytes;  Pointer to member A's list entry     4 bytes;  RTL      3 bytes	jsl Doit	;force another return address on stack	rtl	;return to the List	ManagerDoit	phd	;save direct register	tsc	tcd	;set direct register to point to stack	ldy #8	;(only needed once 8-Mar-93 SS)*** 5-May-91 DAL -- make sure the carry gets set when we leave	ldx #1*** end 5-May-91 DAL	lda [9]	;get size from member A's list entry	cmp [13]	;compare to size in	member B's entry	bcs ABigger	;branch if member A	is bigger;	ldy #8	;member B is bigger	so return	jml endcall	;with carry clearABigger;	ldy #8	;member A is bigger	so return	jml errout	;with carry set	ENDP****************************************************************** MakeString********************************************************************  changed for ROMming purposes - BHM	x6245  1/11/88**  due to changes in DrawSize, we now have the right 0-page.	ENTRY MakeStringMakeString	PROC;This routine is called by ChooseFont and DrawSize.;The calling routine has set A to be the 'size' which is to	be converted;into a string.;convert size into a string	pha	;value to be converted to string;;push pointer to string	lda <FMParamPtr	clc	adc #(TheStr-FMParams)	tax	;temporary storage	lda <FMParamPtr+2	adc #0	pha	sta <temp1Ptr+2	;and save for later	phx	stx <temp1Ptr;	PushWord #3	;string length	PushWord #0	;unsigned conversion	_Int2Dec;remove leading blanks from size string	ldx #3	;length, with blanksRemoveBlanks		;	lda [<temp1Ptr]	and #$00FF	cmp #$20	bne Done	ldy #1	lda [<temp1Ptr],y	dey	sta [<temp1Ptr],y	dex	bra RemoveBlanks;Done	stx <temp2Ptr	;actual length, temp storage	lda [<temp1Ptr]	;first 2 characters	in string	and #$00FF	;first 1	xba	;move it up a byte	ora <temp2Ptr	;and merge string length in;	ldy #(StrLen-FMParams) ;put 'em back	sta [<FMParamPtr],y;	rts	ENDP;                COPY stdstuff****  ProDOS calls changed - 11/4/87;the ProDOS calls now go through the stack-based entry point, and;are no longer self-modifying.  Also, except for GetDirEntry, they;all share parameter block space on 0-page.  Note that the refernce;number - OpenRef, ReadRef, etc. - are actually all the same location.;In particular, after an Open call, the new ref number is in place for;a read call. - BHM	 x6245;;These ProDOS calls	are all the same except for the call number, so;we may combine them in the future.  Pre-computing and saving the;ProDOSParams address would also save a	little time and space.;(Very little.);****************************************************************** CreateFile*****************************************************************	ENTRY CreateFileCreateFile	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea CreateCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** DestroyFile*****************************************************************DestroyFile	PROC Export	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea DestroyCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** OpenFile*****************************************************************	ENTRY OpenFileOpenFile	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea OpenCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** ReadFile*****************************************************************	ENTRY ReadFileReadFile	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea ReadCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** WriteFile*****************************************************************	ENTRY WriteFileWriteFile	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea WriteCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** CloseFile*****************************************************************	ENTRY CloseFileCloseFile	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea CloseCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** SetMark*****************************************************************	ENTRY SetMarkSetMark	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea SetMarkCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** GetEOF*****************************************************************	ENTRY GetEOFGetEOF	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea GetEOFCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP;****************************************************************** SetEOF*****************************************************************	ENTRY SetEOFSetEOF	PROC	pea 0	;high word of parameter block address	tdc	clc	adc #ProDOSParams	;low word	pha	pea SetEOFCall	;call number	jsl StackProDOS	;ProDOS/16 stack-based entry vector	tax	;error code (if any)	rts	ENDP****************************************************************** GetDirEntry*****************************************************************	ENTRY GetDirEntryGetDirEntry	PROC;;GetDirEntry is a little different because its parameter block is in;the FMParams RAM block, rather than on	0-page;	PushZLong <FMParamPtr	pea GDECall	jsl $E100B0	rts	ENDP;;****  end of changed ProDOS calls - BHM	 x6245  11/4/87;****************************************************************** GetHandle** GetHandleXA, added 6-Jan-91 DAL.  Input size = XA, not just A.*****************************************************************	ENTRY GetHandleGetHandle	PROC	ldx #0	export GetHandleXA	;6-Jan-91 DALGetHandleXA		;6-Jan-91 DAL;; Call the Memory Manager to get a block of memory.  The calling routine has put; the low word of the requested size in A.  The handle is returned in A and X.;	ldy #0	phy	;space for result	phy	phx	;hi word of size (was PHY, 6-Jan-91 DAL)	pha	;lo word of size (set by calling proc)	PushZWord <ProgID	;ID	phy	;unpurgeable	phy	;loc not important	phy	_NewHandle	;allocate space	bcc OK	tax	;error code	pla	;clean up	pla	rtsOK	pla	;pull handle off stack	plx	rts	;and return it	ENDP****************************************************************** CheckHandle*****************************************************************	ENTRY CheckHandleCheckHandle	PROC;Check to see if the font handle in the	ID list entry pointed to by IDPtr;is a valid handle.	 Also, store the handle in FontHandle for future use;by the calling routine.	ldy #10	lda [<IDPtr],y	;get handle to font	and save for	sta <FontHandle	;future use by the calling proc	iny	iny	lda [<IDPtr],y	sta <FontHandle+2	ora <FontHandle	;return 'not equal'	if handle is valid	rts	;else return 'equal'	ENDP****************************************************************** CheckNil*****************************************************************	ENTRY CheckNilCheckNil	PROC;Check to see if the handle contained in FontHandle is nil.	lda [<FontHandle]	ldy #2	ora [<FontHandle],y	;return 'not equal'	if handle is not	rts	;nil, else return 'equal'	ENDP****************************************************************** CheckFontID*****************************************************************	ENTRY CheckFontIDCheckFontID	PROC;Y contains fam # to check.  A contains	style/size to check.;If fam # = 0, convert it to system font's fam #.;If fam # and style/size = 0, convert both to system font ID.;If fam # = $FFFF, return error.;If fam # <> 0 and size = 0, return error.	cpy #Illegal	;illegal fam #?	bne NumOK	;no	ldx #FamNumErr	;yes - so return error	sec	rtsNumOK	cpy #0	;is fam # 0?	bne NotZero	;no	ldy <SysFontID	;convert fam # of 0	to system fam #	cmp #0	;is style/size 0?	bne NotZero	;no	lda <SysFontID+2	;convert to system style/size	clc	rtsNotZero	pha	;save style/size	and #$FF00	;get size	bne SizeOK	;OK if not 0	pla	;clean up	ldx #SizeErr	;return error	sec	rtsSizeOK	pla	;retrieve style/size	clc	rts	ENDP****************************************************************** CheckSysFont*****************************************************************	ENTRY CheckSysFontCheckSysFont	PROC;Check to see if the ID list entry pointed to by IDPtr is the system font.	lda [<IDPtr]	cmp <SysFontID	;does fam # match?	bne Ret	;no - so return 'not equal'	ldy #2	lda [<IDPtr],y	cmp <SysFontID+2	;does style/size match?Ret	rts	;return 'equal' if fam # and size/style	ENDP****************************************************************** CopyFamName*****************************************************************	ENTRY CopyFamNameCopyFamName	PROC;Copy the font family name pointed to by TempPtr into the Name list entry;pointed to by NamePtr.	lda [<TempPtr]	and #$00FF	;get length of name	cmp #MaxNameLen+1	;is length OK ?	bcc OK	;yes	lda #MaxNameLen	;no, it's too long - so truncate nameOK	pha	;save new length for later	tay	deyLoop	lda [<TempPtr],y	;copy name into famname list	sta [<NamePtr],y	dey	beq Loop	dey	bpl Loop	lda [<NamePtr]	;get first word of name	and #$FF00	;mask off length byte	ora 1,s	;OR with new length	byte	sta [<NamePtr]	;and save	pla	;clean up	rts	ENDP****************************************************************** CopyFileName*****************************************************************	ENTRY CopyFileNameCopyFileName	PROC****  changed to use FMParams block - BHM  x6245  11/12/87;;Copy the file name	pointed to by FilePtr into the data string FileName.;Adjust the string length of the complete pathname accordingly.;	lda <FMParamPtr	clc	adc #(FileName-FMParams)	sta <tempPtr	;point to filename space	lda <FMParamPtr+2	adc #0	sta <tempPtr+2	lda [<FilePtr]	and #$00FF	;get length of name	tay	clc	adc #DirNameLen+1	;add length of '*:SYSTEM:FONTS:'	pha	;save for later	deyLoop		;	lda [<FilePtr],y	;copy name into pathname string	sta [<tempPtr],y	dey	dey	bpl Loop	ldy #(FileName-FMParams)	lda [<FMParamPtr],y	and #$FF00	;get first byte of filename and make***	ora #$2F	;sure it's a '/'	ora #$3a	;sure it's a ':'	sta [<FMParamPtr],y	ldy #(DirName-FMParams)	lda [<FMParamPtr],y	;get first word of pathname	and #$FF00	;mask off length byte	ora 1,s	;OR with new length	byte	sta [<FMParamPtr],y	;and save	pla	;clean up	rts	ENDP****************************************************************** MakeCurrent*****************************************************************	ENTRY MakeCurrentMakeCurrent	PROC;Make the font pointed to by FontPtr the current font.  IDPtr must point;to the font's ID list entry.;;; This is bad here.  Put it after InflateTextBuffer. 2-Dec-91 DAL;;;	PushZLong <FontHandle;;;	_SetFont	;make font the current font;grow the QuickDraw	text buffer if needed	ldy #8	lda [<FontPtr],y	;get version # of font	cmp #$0100	;version 1.0 ?	beq RomFont	;yes - so handle differently	ldy #10	lda [<FontPtr],y	;get 'fbrExtent' field	bra PushWidthRomFont	lda <RomFbrExtent	;get 'fbrExtent' for ROM fontPushWidth	pha	clc	lda [<FontPtr]	;get 'OffsetToMF' field (in words)	asl a	;convert to bytes	adc #14	tay	lda [<FontPtr],y	;get 'fRectHeight' field	pha	_InflateTextBuffer	;grow QuickDraw text buffer if needed	bcs @barf_SetSysFont ;added 2-Dec-91 DAL;set fields in the QuickDraw GrafPort*** added 2-Dec-91 DAL -- set font now that it's safe!	PushZLong <FontHandle	_SetFont	;make font the current font*** end 2-Dec-91	ldy #2	;get font ID	lda [<IDPtr],y	pha	lda [<IDPtr]	pha	_SetFontID	;set the fontID field in the grafport	ldy #2	lda [<IDPtr],y	;get font style	and #$00FF	pha	_SetTextFace	;set text face field in the grafport	ldy #2	lda [<IDPtr],y	;get font size	and #$FF00	xba	pha	_SetTextSize	;set text size field in the grafport		rts@barf_SetSysFont		;added set system stuff instead of rts		;16-Dec-91 BAK	pha	;save error in A/carry	php		pha	pha	_GetSysFont	;get QD's idea of current system font	_SetFont	;set font handle in the current grafport		pushzlong <SysFontID	_SetFontID	;set font ID in the current grafport		lda <SysFontID+3	and #$00FF	pha	_SetTextSize	;set font size in the current grafport		lda <SysFontID+2	and #$00FF	pha	_SetTextFace	;set font style in the current grafport		plp	;restore error in A/carry	pla			rts	ENDP****************************************************************** IncFilePtr*****************************************************************	ENTRY IncFilePtrIncFilePtr	PROC;Increment FilePtr to point to the next	entry in the File list.	lda [<FilePtr]	;get filename length;;;	and #$000F	;mask off all but length nibble	and #$00ff	;length BYTE (25-Apr-91 DAL)	inc a	;add 1 for the length byte itself	clc	adc <FilePtr	;add to filename ptr	sta <FilePtr	;to create ptr to next filename in list	lda <FilePtr+2	adc #0	sta <FilePtr+2	rts	ENDP****************************************************************** IncIDPtr*****************************************************************	ENTRY IncIDPtrIncIDPtr	PROC;Increment IDPtr to	point to the next entry in the ID list.	clc	lda <IDPtr	adc #14	sta <IDPtr	lda <IDPtr+2	adc #0	sta <IDPtr+2	rts	ENDP****************************************************************** IncFamPtr*****************************************************************	ENTRY IncFamPtrIncFamPtr	PROC;Increment FamPtr to point to the next entry in the Fam list.	clc	lda <FamPtr	adc #6	sta <FamPtr	lda <FamPtr+2	adc #0	sta <FamPtr+2	rts	ENDP****************************************************************** IncNamePtr*****************************************************************	ENTRY IncNamePtrIncNamePtr	PROC;Increment NamePtr to point to the next	entry in the Name list.	lda [<NamePtr]	;get famname length	and #$00FF	inc a	;add 1 for the length byte itself	clc	adc <NamePtr	;add to famname ptr	sta <NamePtr	;to create ptr to next famname in list	lda <NamePtr+2	adc #0	sta <NamePtr+2	rts	ENDP****************************************************************** IncMDPtr*****************************************************************	ENTRY IncMDPtrIncMDPtr	PROC;Increment MDPtr to	point to the next entry in the MD list.	clc	lda <MDPtr	adc #8	sta <MDPtr	lda <MDPtr+2	adc #0	sta <MDPtr+2	rts	ENDP****************************************************************** IncItemPtr*****************************************************************	ENTRY IncItemPtrIncItemPtr	PROC;Increment ItemPtr to point to the next	entry in the Item list.	clc	lda <ItemPtr	adc #2	sta <ItemPtr	lda <ItemPtr+2	adc #0	sta <ItemPtr+2	rts	ENDP****************************************************************** LockFileList*****************************************************************	ENTRY LockFileListLockFileList	PROC	ldx #4	brl Lock	ENDP****************************************************************** UnLockFileList*****************************************************************	ENTRY UnLockFileListUnLockFileList	PROC	ldx #4	brl UnLock	ENDP****************************************************************** LockIDList*****************************************************************	ENTRY LockIDListLockIDList	PROC	ldx #8	brl Lock	ENDP****************************************************************** UnLockIDList*****************************************************************	ENTRY UnLockIDListUnLockIDList	PROC	ldx #8	brl UnLock	ENDP****************************************************************** LockFamList*****************************************************************	ENTRY LockFamListLockFamList	PROC	ldx #12	brl Lock	ENDP****************************************************************** UnLockFamList*****************************************************************	ENTRY UnLockFamListUnLockFamList	PROC	ldx #12	brl UnLock	ENDP****************************************************************** LockNameList*****************************************************************	ENTRY LockNameListLockNameList	PROC	ldx #16	brl Lock	ENDP****************************************************************** UnLockNameList*****************************************************************	ENTRY UnLockNameListUnLockNameList	PROC	lda <MenuMade	;don't unlock NameList if it's been	beq OK	;used in a menu	rtsOK	ldx #16	brl UnLock	ENDP****************************************************************** LockFont*****************************************************************	ENTRY LockFontLockFont	PROC	ldx #20	brl Lock	ENDP****************************************************************** UnLockFont*****************************************************************	ENTRY UnLockFontUnLockFont	PROC	ldx #20	brl UnLock	ENDP****************************************************************** LockBlock*****************************************************************	ENTRY LockBlockLockBlock	PROC	ldx #24	brl Lock	ENDP****************************************************************** UnLockBlock*****************************************************************	ENTRY UnLockBlockUnLockBlock	PROC	ldx #24	brl UnLock	ENDP****************************************************************** LockMDList*****************************************************************	ENTRY LockMDListLockMDList	PROC	ldx #28	brl Lock	ENDP****************************************************************** UnLockMDList*****************************************************************	ENTRY UnLockMDListUnLockMDList	PROC	ldx #28	brl UnLock	ENDP****************************************************************** LockItemList*****************************************************************	ENTRY LockItemListLockItemList	PROC	ldx #32	brl Lock	ENDP****************************************************************** UnLockItemList*****************************************************************	ENTRY UnLockItemListUnLockItemList	PROC	ldx #32	brl UnLock	ENDP****************************************************************** LockFMParams*****************************************************************	ENTRY LockFMParamsLockFMParams	PROC	ldx #36	brl Lock	ENDP****************************************************************** UnLockFMParams*****************************************************************	ENTRY UnLockFMParamsUnLockFMParams	PROC	ldx #36	brl UnLock	ENDP****************************************************************** Lock*****************************************************************	ENTRY LockLock	PROC	lda <TempHandle,x	;copy correct handle into TempHandle	sta <TempHandle	lda <TempHandle+2,x	sta <TempHandle+2	ldy #4	lda [<TempHandle],y	ora #$8000	;set locked bit in attribute word	sta [<TempHandle],y	lda [<TempHandle]	;dereference handle	into correct ptr	sta <TempPtr,x	ldy #2	lda [<TempHandle],y	sta <TempPtr+2,x	rts	ENDP****************************************************************** UnLock*****************************************************************	ENTRY UnLockUnLock	PROC	lda <TempHandle,x	;copy correct handle into TempHandle	sta <TempHandle	lda <TempHandle+2,x	sta <TempHandle+2	ldy #4	lda [<TempHandle],y	and #$7FFF	;clear locked bit in attribute word	sta [<TempHandle],y	rts	ENDP****************************************************************** oStdEnd0*****************************************************************	ENTRY oStdEnd0oStdEnd0	PROC	ldy #0	;# bytes of param to strip	jml oendcall	ENDP****************************************************************** StdEnd4*****************************************************************	ENTRY StdEnd4StdEnd4	PROC	ldy #4	;# bytes of param to strip	jml endcall	ENDP****************************************************************** StdErr4*****************************************************************	ENTRY StdErr4StdErr4	PROC	ldy #4	;# bytes of param to strip	jml errout	ENDP****************************************************************** StdEnd6*****************************************************************	ENTRY StdEnd6StdEnd6	PROC	ldy #6	;# bytes of param to strip	jml endcall	ENDP****************************************************************** StdErr6*****************************************************************	ENTRY StdErr6StdErr6	PROC	ldy #6	;# bytes of param to strip	jml errout	ENDP;                COPY scalestuff;*******************************************************************************			                 **    subroutine AddScaledFont		                 **			                 **              Started 2/10/87		                 **              Bennet Marks  x6245		                 **			                 **  This subroutine takes the newly-scaled font from ScaleFont, enters it     **  into the Font Manager's lists, makes it unpurgeable, and makes it         **  current.			                 **			                 **  The code is adapted from AddFontVar.		                 **			                 *******************************************************************************;****************************************	                  **  9/18/87  10:30 am                  **	                  ****************************************;	ENTRY AddScaledFontAddScaledFont	PROC	INCLUDE 'SomeFMEqus' ;added 2/12/87 - BHM;	sta <FontHandle	stx <FontHandle+2;	jsr LockFont	; Add call to routine here that will find any old entries with this ID and type/size; dispose of the handle in it and set IDPtr to the newly empty entry. This way; it can be reused	jsr FindOldEntry	; find first entry with this type/ID	bcc IDSetup	; if found use it...**  Add for now - experimental:	jsr UnlockIDList	lda <IDListSize	;get current size of ID list	clc	adc #14	;add size of new entry	sta <NewIDSize	;and save	PushWord #0	;hi word of size	pha	;lo word of size	PushZLong <IDHandle	;handle to list	_SetHandleSize	;grow the list	bcc OK	pha	;save error code	jsr UnLockFont	;clean up	jsr LockIDList	;exper.	pla	;retrieve error code	plx	;pull of font stat bits	plx	;pull off fam name offset	sec	rtl;OK	jsr LockIDList	clc	lda <IDPtr	;create ptr to new ID entry	adc <IDListSize	sta <IDPtr	lda <IDPtr+2	adc #0	sta <IDPtr+2;; Create alternate entry point for case when the idptr is going to be an existing entry; 6/12/89 MenschIDSetup	ldy #2	lda [<fontPtr],y	;fam num	sta [<IDPtr]	ldy #4	lda [<FontPtr],y	;get font's style word	and #$00FF	;mask off hi byte	pha	;save on stack	iny	iny	lda [<FontPtr],y	;get font's size word	and #$00FF	;mask off hi byte	xba	;swap bytes	ora 1,s	;OR with style word	ply	;clean up	ldy #2	sta [<IDPtr],y	;save style/size word in new ID entry;**  Let's wipe out all references to BestPtr**  (exper.);	lda <NewLevel	;temp storage for font stat bits	and #(ApFamBit+ApVarBit) ;inherit these	two bits	ora #(MemBit+UnrealBit+NotDiskBit);(those 3 are set to 1's; the leftovers are 0)	ldy #8	sta [<IDPtr],y;	lda <MatchLevel	;temp. storage for offset to fam name	ldy #4	sta [<IDPtr],y	lda #0	ldy #6	sta [<IDPtr],y	;set filename offset to 0;;	lda <FontHandle	;get font handle	ldy #10	sta [<IDPtr],y	;and save in new ID	entry	lda <FontHandle+2	iny	iny	sta [<IDPtr],y	lda <NewIDSize	;get new size of ID	list	sta <IDListSize	;and save	inc <IDCount	;inc # of ID entries	Pushword #0	PushZLong <FontHandle	_SetPurge	;make font unpurgeable	jsr MakeCurrent	;make new font the current font	 	pha	;12/16/91 BAK added error propagation	php	;12/16/91 BAK	jsr UnLockFont	;clc	;signal no error		plp	;12/16/91 BAK	pla	;12/16/91 BAK		rtl	;; Routine to find the old entry and set the IDPtr to it...FindOldEntrythisFam	equ 1thisStyle	equ thisFam+2	ldy #4	lda [<FontPtr],y	;get font's style word	and #$00FF	;mask off hi byte	pha	;save on stack	iny	iny	lda [<FontPtr],y	;get font's size word	and #$00FF	;mask off hi byte	xba	;swap bytes	ora 1,s	;OR with style word	sta 1,s	;save style/size on the stack...	ldy #2	lda [<fontPtr],y	; fam num	pha	; save family number on the stack	jsr LockIDList		ldx #0	;# of ID entries processed	ldy #2Loop	lda [<IDPtr]	;get fam #	cmp thisFam,s	;match?	bne NextID	;no	lda [<IDPtr],y	;get style/size	cmp thisStyle,s	;match?	beq GotID	;yesNextID	jsr IncIDPtr	inx	cpx <IDCount	;at end of list?	bne Loop	;noNotFound	pla	; pull off the crap....	pla	sec	; set carry to indicate not found	rtsGotID	ldy #10	; be sure to dispose the handle	lda [<IDPtr],y	tax	ldy #12	lda [<IDPtr],y	tay	jsr DisposeTheHandle	; throw the old font away...		pla	; pull off the crap	pla	clc	; send we found it message back...	rts	ENDP			********************************************************************************* Dispose a handle** Input: X,Y = handle** Output: none********************************************************************************DisposeTheHandle	PROC	phy	phx	_DisposeHandle	rts	ENDP	END